mapper.select:
SELECT A.SEQNO, B.CREDIT_TAG_ID, T.Org_Type, T.Credit_Type, A.CREDIT_AMT / 100000000 creditAmt, B.term, B.Term_Unit, T.Risk_Ratio, A.MDATE MDATE, A.Update_Time timeUpdate, A.Remark, A.CUSTOMER_ID customerId, A.PFLSH PFLSH, C.CUSTOMER_NAME as customerName, A.CCY FROM CREDIT_LINES A left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID = C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID = D.CUSTOMER_ID LEFT JOIN CREDIT_CONF_INFO B on B.CREDIT_MST_ID = A.CREDIT_MST_ID LEFT JOIN CREDIT_TAG_INFO T on B.CREDIT_TAG_ID = T.CREDIT_TAG_ID
A.CREDIT_TYPE='04'
AND A.SEQNO = #{seqno,jdbcType=VARCHAR}
